//! Cross-language test vectors. `tests/vectors/rust.json` is generated here
//! and checked by packages/sync-js; `tests/vectors/ts.json` is generated by
//! packages/sync-js and checked here. Both sides also re-seal every vector
//! with its fixed ephemeral key and nonce and compare the bytes.
//!
//! Regenerate with `HAME_SYNC_WRITE_VECTORS=1 cargo test -p hame-sync --test vectors`.

use hame_sync::PublicIdentity;
use hame_sync::envelope::{Header, Sealed, seal_with};
use hame_sync::keys::{Identity, b64, unb64, unb64_32};
use hame_sync::pairing::{
    GRANT_LIST_KIND, Grant, GrantEntry, GrantList, PairingOffer, SignedGrant, SignedGrantList,
    pairing_proof, sas,
};
use serde_json::{Value, json};
use sha2::{Digest, Sha256};

fn seed(label: &str) -> [u8; 32] {
    Sha256::digest(label.as_bytes()).into()
}

fn identity(label: &str) -> (Identity, Value) {
    let ed = seed(&format!("{label}/ed"));
    let x = seed(&format!("{label}/x"));
    let id = Identity::from_seeds(&ed, &x);
    let public = id.public();
    (
        id,
        json!({"ed_seed": b64(&ed), "x_seed": b64(&x), "ed": b64(&public.ed), "x": b64(&public.x)}),
    )
}

fn generate() -> Value {
    let plaintexts: Vec<(&str, Vec<u8>)> = vec![
        (
            "request frame",
            br#"{"t":"req","id":7,"method":"POST","path":"/api/sessions/abc/prompt","body":{"text":"hi"}}"#
                .to_vec(),
        ),
        ("empty", Vec::new()),
        ("unicode", "héllo — 世界 🚀".as_bytes().to_vec()),
        ("binary", (0..1000u32).map(|n| (n * 7 % 256) as u8).collect()),
    ];
    let mut envelopes = Vec::new();
    for (n, (name, plaintext)) in plaintexts.iter().enumerate() {
        let (sender, sender_json) = identity(&format!("rust/sender/{n}"));
        let (recipient, recipient_json) = identity(&format!("rust/recipient/{n}"));
        let ephemeral = seed(&format!("rust/ephemeral/{n}"));
        let nonce: [u8; 24] = seed(&format!("rust/nonce/{n}"))[..24].try_into().unwrap();
        let header = Header::new(
            &format!("device-{n}"),
            &format!("host-{n}"),
            &format!("{}", 7 + n),
            1_763_000_000_000_000 + n as u64,
        );
        let bytes = seal_with(
            &sender,
            &recipient.public().x,
            &header,
            plaintext,
            &ephemeral,
            &nonce,
        )
        .unwrap();
        envelopes.push(json!({
            "name": name,
            "sender": sender_json,
            "recipient": recipient_json,
            "ephemeral_seed": b64(&ephemeral),
            "nonce": b64(&nonce),
            "header": header,
            "plaintext": b64(plaintext),
            "envelope": b64(&bytes),
        }));
    }

    let mut pairing = Vec::new();
    for n in 0..3 {
        let (host, host_json) = identity(&format!("rust/host/{n}"));
        let (client, client_json) = identity(&format!("rust/client/{n}"));
        let secret = seed(&format!("rust/secret/{n}"));
        let offer = PairingOffer {
            relay: format!("https://relay.example.com:8443/base path/{n}?q=a&b"),
            host: format!("host {n}"),
            host_keys: host.public(),
            secret,
            expires: 1_763_000_600 + n,
        };
        pairing.push(json!({
            "host": host_json,
            "client": client_json,
            "secret": b64(&secret),
            "relay": offer.relay,
            "host_id": offer.host,
            "exp": offer.expires,
            "uri": offer.to_uri(),
            "mac": b64(&pairing_proof(&secret, &client.public())),
            "sas": sas(&secret, &host.public().ed, &client.public().ed),
        }));
    }

    let fingerprints: Vec<Value> = (0..3)
        .map(|n| {
            let (id, json) = identity(&format!("rust/fingerprint/{n}"));
            json!({"keys": json, "fingerprint": id.public().fingerprint()})
        })
        .collect();

    let (host, host_json) = identity("rust/grant/host");
    let (device, _) = identity("rust/grant/device");
    let grant = Grant {
        v: 1,
        host: "host-1".into(),
        device: "device-1".into(),
        ed: b64(&device.public().ed),
        x: b64(&device.public().x),
        label: "Phone ✓".into(),
        issued: 1_763_000_000,
    };
    let signed = grant.sign(&host);
    let list = GrantList {
        kind: GRANT_LIST_KIND.into(),
        v: 1,
        host: "host-1".into(),
        devices: vec![GrantEntry {
            device: "device-1".into(),
            ed: b64(&device.public().ed),
            x: b64(&device.public().x),
            label: "Phone ✓".into(),
        }],
        issued: 1_763_000_000,
    };
    let signed_list = list.sign(&host);
    json!({
        "comment": "Generated by crates/hame-sync/tests/vectors.rs. Base64url without padding throughout.",
        "envelopes": envelopes,
        "pairing": pairing,
        "fingerprints": fingerprints,
        "grants": [{"host": host_json, "grant": grant, "signed": signed}],
        "grant_lists": [{"host": host_json, "list": list, "signed": signed_list}],
    })
}

fn vectors_dir() -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/vectors")
}

fn keys_of(value: &Value) -> (Identity, PublicIdentity) {
    let id = Identity::from_seeds(
        &unb64_32(value["ed_seed"].as_str().unwrap()).unwrap(),
        &unb64_32(value["x_seed"].as_str().unwrap()).unwrap(),
    );
    let public = id.public();
    assert_eq!(b64(&public.ed), value["ed"]);
    assert_eq!(b64(&public.x), value["x"]);
    (id, public)
}

/// Checks a vector file produced by either language.
fn check(vectors: &Value) {
    for vector in vectors["envelopes"].as_array().unwrap() {
        let name = vector["name"].as_str().unwrap();
        let (sender, sender_public) = keys_of(&vector["sender"]);
        let (recipient, recipient_public) = keys_of(&vector["recipient"]);
        let text = vector["envelope"].as_str().unwrap();
        let sealed = Sealed::parse(text).unwrap();
        let header: Header = serde_json::from_value(vector["header"].clone()).unwrap();
        assert_eq!(sealed.header, header, "{name}");
        let plain = sealed
            .open(
                &recipient,
                &header.to,
                &sender_public,
                Some(header.counter - 1),
            )
            .unwrap();
        assert_eq!(
            plain.to_vec(),
            unb64(vector["plaintext"].as_str().unwrap()).unwrap(),
            "{name}"
        );
        // The same inputs seal to the same bytes here.
        let again = seal_with(
            &sender,
            &recipient_public.x,
            &header,
            &plain,
            &unb64_32(vector["ephemeral_seed"].as_str().unwrap()).unwrap(),
            &unb64(vector["nonce"].as_str().unwrap())
                .unwrap()
                .try_into()
                .unwrap(),
        )
        .unwrap();
        assert_eq!(b64(&again), text, "{name}");
        // And a flipped byte is refused.
        let mut bytes = unb64(text).unwrap();
        let at = bytes.len() / 2;
        bytes[at] ^= 0x80;
        let refused = Sealed::from_bytes(bytes)
            .and_then(|s| s.open(&recipient, &header.to, &sender_public, None));
        assert!(refused.is_err(), "{name}");
    }
    for vector in vectors["pairing"].as_array().unwrap() {
        let (_, host) = keys_of(&vector["host"]);
        let (_, client) = keys_of(&vector["client"]);
        let secret = unb64_32(vector["secret"].as_str().unwrap()).unwrap();
        let offer = PairingOffer::parse(vector["uri"].as_str().unwrap()).unwrap();
        assert_eq!(offer.relay, vector["relay"]);
        assert_eq!(offer.host, vector["host_id"]);
        assert_eq!(offer.expires, vector["exp"].as_u64().unwrap());
        assert_eq!(offer.host_keys, host);
        assert_eq!(offer.secret, secret);
        assert_eq!(offer.to_uri(), vector["uri"]);
        assert_eq!(b64(&pairing_proof(&secret, &client)), vector["mac"]);
        assert_eq!(sas(&secret, &host.ed, &client.ed), vector["sas"]);
    }
    for vector in vectors["fingerprints"].as_array().unwrap() {
        let (_, keys) = keys_of(&vector["keys"]);
        assert_eq!(keys.fingerprint(), vector["fingerprint"]);
    }
    for vector in vectors["grants"].as_array().unwrap() {
        let (host, host_public) = keys_of(&vector["host"]);
        let signed: SignedGrant = serde_json::from_value(vector["signed"].clone()).unwrap();
        let grant = signed.verify(&host_public.ed).unwrap();
        assert_eq!(serde_json::to_value(&grant).unwrap(), vector["grant"]);
        assert_eq!(grant.sign(&host), signed);
    }
    // Grant lists as published to the relay: a plain Ed25519 signature over
    // the document bytes, which is what the relay verifies.
    for vector in vectors["grant_lists"].as_array().unwrap() {
        let (host, host_public) = keys_of(&vector["host"]);
        let signed: SignedGrantList = serde_json::from_value(vector["signed"].clone()).unwrap();
        let document = unb64(&signed.document).unwrap();
        let signature: [u8; 64] = unb64(&signed.signature).unwrap().try_into().unwrap();
        hame_sync::keys::verify_signature(&host_public.ed, &document, &signature).unwrap();
        let list = signed.verify(&host_public.ed).unwrap();
        assert_eq!(serde_json::to_value(&list).unwrap(), vector["list"]);
        assert_eq!(list.sign(&host), signed);
    }
}

#[test]
fn rust_vectors_are_current_and_valid() {
    let generated = generate();
    let path = vectors_dir().join("rust.json");
    if std::env::var_os("HAME_SYNC_WRITE_VECTORS").is_some() {
        std::fs::create_dir_all(vectors_dir()).unwrap();
        std::fs::write(
            &path,
            serde_json::to_string_pretty(&generated).unwrap() + "\n",
        )
        .unwrap();
    }
    let stored: Value = serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
    assert_eq!(
        stored, generated,
        "regenerate with HAME_SYNC_WRITE_VECTORS=1"
    );
    check(&stored);
}

#[test]
fn typescript_vectors_verify_in_rust() {
    let path = vectors_dir().join("ts.json");
    let stored: Value = serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
    assert!(!stored["envelopes"].as_array().unwrap().is_empty());
    check(&stored);
}
